using System.ComponentModel;
using System.Text.Json;
using System.Text.Json.Nodes;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;
namespace PowerShapeMcp;
[McpServerToolType]
public sealed class SurfaceScaleTools(BridgeSession session) {
 [McpServerTool(Name="prepare_owned_surface_scale",ReadOnly=false,Destructive=false,Idempotent=false,OpenWorld=false)]
 [Description("Prepare one experimental uniform scale of an explicit SURFACE among1..8SURFACEs in an owned mm/WORLD/idle/empty-selection copy. Positive factor0.01..100 except1 and bounded explicit WORLD centre come from prepare_uniform_scale_plan. Captures all surface UV point/normal witnesses with explicit known grid. No CAD mutation, selection or save; disabled source packet, separate execution and verification required. Native bounds unavailable; full only and default-off flag.")]
 public Task<CallToolResult> Prepare([Description("Passive scalePlanHandle for the exact one-SURFACE set and explicit factor/centre.")]string scalePlanHandle,[Description("Fresh binding for this owned working copy.")]string workingDocumentBindingHandle,[Description("Known tStart,tEnd,tDivisions,uStart,uEnd,uDivisions for every surface; divisions1..4. No UV-domain inference.")]JsonElement surfaceGrid,CancellationToken cancellationToken)=>new SolidScaleTools(session,true).Run("prepare_owned_surface_scale",new(){["scalePlanHandle"]=scalePlanHandle,["workingDocumentBindingHandle"]=workingDocumentBindingHandle,["surfaceGrid"]=JsonNode.Parse(surfaceGrid.GetRawText())},cancellationToken);
 [McpServerTool(Name="execute_owned_surface_scale",ReadOnly=false,Destructive=true,Idempotent=false,OpenWorld=false)]
 [Description("Execute the prepared one-SURFACE uniform NOKEEP scale once through a fixed13phase command program. Consumes intent/CAD leases, selects only this surface, clears only after all successful phases. Returned execution remains fenced until separate verification. No save/OPEN/activation/mouse. Unknown stops with no automatic CANCEL/DISMISS/clear/inverse/replay. Explicit-UV sampled profile can reject changed parameterization; no full topology. Full only.")]
 public Task<CallToolResult> Execute([Description("Unconsumed ownedSurfaceScaleHandle from prepare_owned_surface_scale in this connection.")]string ownedSurfaceScaleHandle,CancellationToken cancellationToken)=>new SolidScaleTools(session,true).Run("execute_owned_surface_scale",new(){["ownedSolidScaleHandle"]=ownedSurfaceScaleHandle},cancellationToken);
 [McpServerTool(Name="verify_owned_surface_scale",ReadOnly=false,Destructive=false,Idempotent=false,OpenWorld=false)]
 [Description("Independently verify the original complete13phase SURFACE scale and later fresh context. Checks declared affine UV points, positive-scale normal directions, raw-area square law and exact other-surface/visibility/layout/ownership/files/windows preservation. May complete original journal and release only matching fence. No CAD command or retry. Bounds unavailable; sampled explicit-UV behavior, not topology or saved persistence. Full only.")]
 public Task<CallToolResult> Verify([Description("Original Native execution request ID.")]string executionRequestId,[Description("Exact original immutable raw execution SHA256.")]string executionReceiptSha256,[Description("Fresh post-return candidate document handle.")]string candidateDocumentHandle,[Description("Fresh one-use active document listing handle.")]string activeDocumentHandle,CancellationToken cancellationToken)=>new SolidScaleTools(session,true).Run("verify_owned_surface_scale",new(){["executionRequestId"]=executionRequestId,["executionReceiptSha256"]=executionReceiptSha256,["candidateDocumentHandle"]=candidateDocumentHandle,["activeDocumentHandle"]=activeDocumentHandle},cancellationToken);
 public static McpServerTool[] Create(BridgeSession s){if(!s.PreparedEnabled("prepare_owned_surface_scale"))return[];var t=new SurfaceScaleTools(s);var prepare=SolidQuarterTurnTools.Schema("scalePlanHandle","workingDocumentBindingHandle");prepare["properties"]!["surfaceGrid"]=SurfaceReadTools.GridSchema(4);prepare["required"]!.AsArray().Add("surfaceGrid");return[new StrictTool(McpServerTool.Create(t.Prepare),s,prepare,x=>ExecutionTools.ValidateSurfaceGrid(x["surfaceGrid"]!.AsObject())),new StrictTool(McpServerTool.Create(t.Execute),s,SolidQuarterTurnTools.Schema("ownedSurfaceScaleHandle")),new StrictTool(McpServerTool.Create(t.Verify),s,SolidQuarterTurnTools.Schema("executionRequestId","executionReceiptSha256","candidateDocumentHandle","activeDocumentHandle"))];}
}
